content.text:
            "source_urls still contain an unresolved aggregator wrapper "
            f"({aggregator_hits[0]}) — run resolve_url.py and store the publisher URL",
        ))
    else:
        results.append(("source_urls_resolved", True, "publisher URLs (no aggregator wrappers)"))

    prose = str(data.get("aggregated_raw_content") or "")
    words = len(prose.split())
    ratio = _markup_ratio(prose)
    if words >= PROSE_MIN_WORDS and ratio < 0.05:
        results.append(("prose_quality", True, f"{words} words, clean prose"))
    elif words < PROSE_MIN_WORDS:
        results.append((
            "prose_quality",
            False,
            f"aggregated_raw_content is only {words} words — need >= {PROSE_MIN_WORDS} "
            "of substantive article text",
        ))
    else:
        results.append((
            "prose_quality",
            False,
            "aggregated_raw_content looks like markup, not prose — scrape the "
            "article body, not the page HTML",
        ))

    return results


def run_headline_scan_checks(
    data: dict | None, raw_text: str
) -> list[tuple[str, bool, str]]:
    """HEADLINE_SCAN checklist. Returns list of (rule, passed, detail)."""
    results: list[tuple[str, bool, str]] = []

    guards = _garbage_guards(raw_text)
    if guards:
        return guards

    if data is None:
        data, err = extract_json_block(raw_text)
    if data is None:
        return [("parseable_json", False, "no parseable JSON object found in output")]
    results.append(("parseable_json", True, "single JSON object"))

    if data.get("status") == "error":
        reason = str(data.get("reason") or "").strip()
        if reason in KNOWN_ERROR_REASONS or reason:
            results.append(("clean_error_json", True, f"error-json ({reason or 'no candidates'})"))
            return results

    candidates = data.get("candidates")
    if not isinstance(candidates, list) or not candidates:
        results.append(("candidates_present", False, "candidates must be a non-empty list"))
        return results
    results.append(("candidates_present", True, f"{len(candidates)} candidates"))

    bad_fields: list[int] = []
    aggregator_hits: list[str] = []
    for idx, c in enumerate(candidates, 1):
        if not isinstance(c, dict) or any(not c.get(k) for k in HEADLINE_REQUIRED_PER_CANDIDATE):
            bad_fields.append(idx)
            continue
        url = str(c.get("url") or "")
        if is_aggregator_url(url):
            aggregator_hits.append(url)

    if bad_fields:
        results.append((
            "candidate_fields",
            False,
            f"candidates missing {HEADLINE_REQUIRED_PER_CANDIDATE} at index(es): {bad_fields[:5]}",
        ))
    else:
        results.append(("candidate_fields", True, "every candidate has headline/url/source"))

    if aggregator_hits:
        results.append((
            "candidate_urls_resolved",
            False,
            f"candidate URL still an aggregator wrapper ({aggregator_hits[0]}) — "
            "run resolve_url.py at scan time",
        ))
    else:
        results.append(("candidate_urls_resolved", True, "publisher URLs (no aggregator wrappers)"))

    return results


def validate_file(path: str, mode: str) -> tuple[bool, list[tuple[str, bool, str]]]:
    """Read a file and run the mode's checks. Returns (all_passed, results)."""
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            raw_text = f.read()
    except OSError as e:
        return False, [("file_readable", False, f"cannot read file: {e}")]

    if not raw_text.strip():
        return False, [("not_empty", False, "output file is empty")]

    data, _ = extract_json_block(raw_text)
    if mode == "headline_scan":
        results = run_headline_scan_checks(data, raw_text)
    else:
        results = run_deep_research_checks(data, raw_text)
    return all(ok for _, ok, _ in results), results


def print_report(results: list[tuple[str, bool, str]]) -> bool:
    all_pass = True
    for name, ok, detail in results:
        if ok:
            print(f"PASS: {name} — {detail}")
        else:
            all_pass = False
            print(f"FAIL: {name} — {detail}")
    print(f"RESEARCH_CHECK: {'PASS' if all_pass else 'FAIL'}")
    return all_pass


def main() -> int:
    parser = argparse.ArgumentParser(description="Combined research validator")
    parser.add_argument("--file", required=True, help="Path to the research JSON output")
    parser.add_argument(
        "--mode",
        choices=["deep_research", "headline_scan"],
        default="deep_research",
        help="Which mode's checks to run (default deep_research)",
    )
    args = parser.parse_args()

    ok, results = validate_file(args.file, args.mode)
    print_report(results)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
extract_article.py — Multi-tier article extraction with tested fallbacks.

Usage:
  python3 extract_article.py "<url>"
  python3 extract_article.py --json "<url>"

Prints extracted markdown/text to stdout. On success prints EXTRACT_OK to stderr
with tier and word count. Exit 0 on success, 1 if all tiers fail.

Fallback ladder (required tiers use installed tools only):
  1. trafilatura -u <url>
  2. curl + trafilatura on downloaded HTML
  3. requests + selectolax/bs4 text extraction
  4. (optional) lynx -dump if installed
  5. (optional) web-reader-pro WebFetch tier if markdownify/diskcache available
"""
from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from html import unescape

UA = "Mozilla/5.0 (compatible; OpenClawScout/1.0)"
MIN_WORDS = 50
CURL_TIMEOUT = 20


def word_count(text: str) -> int:
    return len(re.findall(r"\w+", text or ""))


def clean_text(text: str) -> str:
    text = re.sub(r"\n{3,}", "\n\n", text or "")
    return text.strip()


def tier_trafilatura_url(url: str) -> tuple[str, str] | None:
    traf = shutil.which("trafilatura")
    if not traf:
        try:
            import trafilatura as traf_mod

            downloaded = traf_mod.fetch_url(url)
            if downloaded:
                text = traf_mod.extract(downloaded, output_format="markdown")
                if text and word_count(text) >= MIN_WORDS:
                    return "trafilatura_module", clean_text(text)
        except Exception:
            pass
        return None
    try:
        proc = subprocess.run(
            [traf, "-u", url, "--output-format", "markdown"],
            capture_output=True,
            text=True,
            timeout=CURL_TIMEOUT + 10,
        )
        if proc.returncode == 0 and proc.stdout and word_count(proc.stdout) >= MIN_WORDS:
            return "trafilatura_cli", clean_text(proc.stdout)
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def tier_curl_trafilatura(url: str) -> tuple[str, str] | None:
    curl = shutil.which("curl")
    traf = shutil.which("trafilatura")
    if not curl:
        return None
    try:
        proc = subprocess.run(
            ["curl", "-sL", "-A", UA, "--max-time", str(CURL_TIMEOUT), url],
            capture_output=True,
            timeout=CURL_TIMEOUT + 5,
        )
        if proc.returncode != 0 or not proc.stdout:
            return None
        html_bytes = proc.stdout
        if traf:
            with tempfile.NamedTemporaryFile(suffix=".html", delete=False) as f:
                f.write(html_bytes)
                tmp = f.name
            try:
                proc2 = subprocess.run(
                    [traf, "-i", tmp, "--output-format", "markdown"],
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if proc2.returncode == 0 and proc2.stdout and word_count(proc2.stdout) >= MIN_WORDS:
                    return "curl_trafilatura", clean_text(proc2.stdout)
            finally:
                os.unlink(tmp)
        try:
            import trafilatura as traf_mod

            text = traf_mod.extract(html_bytes.decode("utf-8", errors="replace"), output_format="markdown")
            if text and word_count(text) >= MIN_WORDS:
                return "curl_trafilatura_module", clean_text(text)
        except Exception:
            pass
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def tier_bs4(url: str) -> tuple[str, str] | None:
    try:
        import requests
    except ImportError:
        return None
    try:
        resp = requests.get(url, headers={"User-Agent": UA}, timeout=CURL_TIMEOUT)
        resp.raise_for_status()
        html = resp.text
    except Exception:
        return None

    text = ""
    try:
        from selectolax.parser import HTMLParser

        tree = HTMLParser(html)
        for bad in tree.css("script, style, nav, footer, header, aside, noscript"):
            bad.decompose()
        body = tree.body
        text = body.text(separator="\n") if body else tree.text()
    except Exception:
        try:
            from bs4 import BeautifulSoup

            soup = BeautifulSoup(html, "lxml")
            for tag in soup(["script", "style", "nav", "footer", "header", "aside"]):
                tag.decompose()
            text = soup.get_text("\n")
        except Exception:
            return None

    text = clean_text(unescape(re.sub(r"[ \t]+\n", "\n", text)))
    if word_count(text) >= MIN_WORDS:
        return "bs4_selectolax", text
    return None


def tier_lynx(url: str) -> tuple[str, str] | None:
    lynx = shutil.which("lynx")
    if not lynx:
        return None
    try:
        proc = subprocess.run(
            [lynx, "-dump", url],
            capture_output=True,
            text=True,
            timeout=CURL_TIMEOUT + 10,
        )
        text = clean_text(proc.stdout[:8000] if proc.stdout else "")
        if word_count(text) >= MIN_WORDS:
            return "lynx", text
    except (subprocess.SubprocessError, OSError):
        pass
    return None


def tier_webfetch(url: str) -> tuple[str, str] | None:
    try:
        import requests
        from bs4 import BeautifulSoup
        from markdownify import markdownify as md
    except ImportError:
        return None
    try:
        resp = requests.get(url, headers={"User-Agent": UA}, timeout=CURL_TIMEOUT)
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, "lxml")
        for tag in soup(["script", "style", "nav", "footer", "header"]):
            tag.decompose()
        article = soup.find("article") or soup.find("main") or soup.body
        if not article:
            return None
        text = clean_text(md(str(article), heading_style="ATX"))
        if word_count(text) >= MIN_WORDS:
            return "webfetch_markdownify", text
    except Exception:
        pass
    return None


def extract(url: str) -> dict:
    url = (url or "").strip()
    if not url:
        return {"ok": False, "error": "empty_url", "tier": None, "content": "", "words": 0}


